export const DATABASE_MODELS_BY_NAME: Record<string, DatabaseModel> = DATABASE_MODELS.reduce(
  (acc, m) => {
    acc[m.modelName] = m
    return acc
  },
  {} as Record<string, DatabaseModel>,
)

export const DATABASE_MODEL_NAMES = [
  'Address',
  'ApiToken',
  'AuditLog',
  'Country',
  'Email',
  'Invite',
  'Link',
  'LoginAttempt',
  'OAuthAccount',
  'Organization',
  'OrganizationMember',
  'Permission',
  'PhoneNumber',
  'Plan',
  'Role',
  'SecurityEvent',
  'Subscription',
  'Team',
  'TeamMember',
  'StoredFile',
  'User',
  'UserPreference',
  'UserSession',
] as const

export type DatabaseModelName = (typeof DATABASE_MODEL_NAMES)[number]

// Helper functions
export function getDatabaseModel(modelName: string): DatabaseModel | undefined {
  return DATABASE_MODELS_BY_NAME[modelName]
}

export function getDatabaseModelFields(modelName: string): DatabaseField[] {
  const model = getDatabaseModel(modelName)
  return model ? model.fields : []
}

export function getDatabaseModelField(
  modelName: string,
  fieldName: string,
): DatabaseField | undefined {
  const fields = getDatabaseModelFields(modelName)
  return fields.find(field => field.name === fieldName)
}
